// Adaptive Sorting Algorithm Implementation
// This program implements a sorting algorithm that can be evolved to adapt to different data patterns

use std::cmp::Ordering;

// HYPOTHESIS-1: Adding a sorted-data fast path and using sort_unstable as fallback for deep recursion will improve both score and performance
// MECHANISM-1: Early return on sorted data reduces avg_time variance (better adaptability); depth limit prevents worst-case; shorter code reduces length penalty
// EXPECT-1: score > 0.9995
// RESULT-1: REFUTED (actual=0.9988975757925741)
// HYPOTHESIS-2: Keeping a compact custom sort with 3-way partition maintains diversity from pure stdlib solutions while being competitive
// MECHANISM-2: The 3-way partition handles duplicates well; combined with stdlib fallback it gets near-optimal performance with unique feature coordinates
// EXPECT-2: performance_score > 0.999
// RESULT-2: REFUTED (actual=0.9982898874945466)

pub fn adaptive_sort<T: Ord>(a: &mut [T]) {
    let d = (a.len() as f64).log2() as usize * 2;
    qsort(a, d);
}
fn qsort<T: Ord>(a: &mut [T], d: usize) {
    let n = a.len();
    if n < 2 { return; }
    if a.windows(2).all(|w| w[0] <= w[1]) { return; }
    if n <= 16 || d == 0 { a.sort_unstable(); return; }
    let (m, h) = (n/2, n-1);
    if a[0]>a[m] { a.swap(0,m); }
    if a[0]>a[h] { a.swap(0,h); }
    if a[m]>a[h] { a.swap(m,h); }
    a.swap(m,h);
    let (mut lt, mut i, mut gt) = (0,0,h);
    while i<gt {
        match a[i].cmp(&a[h]) {
            Ordering::Less => { a.swap(lt,i); lt+=1; i+=1; }
            Ordering::Greater => { gt-=1; a.swap(i,gt); }
            _ => i+=1
        }
    }
    a.swap(gt,h);
    qsort(&mut a[..lt], d-1);
    qsort(&mut a[gt+1..], d-1);
}
// EVOLVE-BLOCK-END

// Benchmark function to test the sort implementation
pub fn run_benchmark(test_data: Vec<Vec<i32>>) -> BenchmarkResults {
    let mut results = BenchmarkResults {
        times: Vec::new(),
        correctness: Vec::new(),
        adaptability_score: 0.0,
    };

    for data in test_data {
        let mut arr = data.clone();
        let start = std::time::Instant::now();

        adaptive_sort(&mut arr);

        let elapsed = start.elapsed();
        results.times.push(elapsed.as_secs_f64());

        // Check if correctly sorted
        let is_sorted = arr.windows(2).all(|w| w[0] <= w[1]);
        results.correctness.push(is_sorted);
    }

    // Calculate adaptability score based on performance variance
    if results.times.len() > 1 {
        let mean_time: f64 = results.times.iter().sum::<f64>() / results.times.len() as f64;
        let variance: f64 = results.times.iter()
            .map(|t| (t - mean_time).powi(2))
            .sum::<f64>() / results.times.len() as f64;

        // Lower variance means better adaptability
        results.adaptability_score = 1.0 / (1.0 + variance.sqrt());
    }

    results
}

#[derive(Debug)]
pub struct BenchmarkResults {
    pub times: Vec<f64>,
    pub correctness: Vec<bool>,
    pub adaptability_score: f64,
}

#[cfg(test)]
